#### From mathcomp Require Import all_ssreflect all_algebra. From mathcomp Require Import reals geometry classical_sets. Set Implicit Arguments. Unset Strict Implicit. Unset Printing Implicit Defensive. Section putnam_2021_a5. Variable R : realType. Record point := mkPoint { x : R ; y : R }. Definition dist (A B : point) : R := sqrt ((x A - x B)^+2 + (y A - y B)^+2). Variables A B C D : point. Hypothesis parallelogram_ABCD : exists v1 v2 : point, A = v1 /\ B = v2 /\ exists u v : R, u <> 0 /\ v <> 0 /\ B = mkPoint (x A + u * (x D - x A)) (y A + u * (y D - y A)) /\ C = mkPoint (x B + (x D - x A)) (y B + (y D - y A)) /\ D = mkPoint (x A + (x D - x A)) (y A + (y D - y A)). Hypothesis angle_BAD_acute : 0 < acos (((x B - x A) * (x D - x A) + (y B - y A) * (y D - y A)) / (dist A B * dist A D)). Theorem acute_angle_midpoint_area : exists area : R, area > 0. Proof. Admitted. End
